from collections import deque
R,C=16,16
seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  if grid[r][c]!=7 and (r,c) not in seen:
   q=[(r,c)]; seen.add((r,c)); cells=[]
   while q:
    x,y=q.pop();cells.append((x,y))
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     nx,ny=x+dx,y+dy
     if 0<=nx<R and 0<=ny<C and grid[nx][ny]!=7 and (nx,ny) not in seen:
      seen.add((nx,ny));q.append((nx,ny))
   comps.append(cells)
[(len(x), (min(r for r,c in x),max(r for r,c in x),min(c for r,c in x),max(c for r,c in x)), sorted(set(grid[r][c] for r,c in x if grid[r][c]))) for x in comps]

target={2,4,6}
out=[row[:] for row in grid]
for comp in comps:
 vals=set(grid[r][c] for r,c in comp if grid[r][c] not in (0,7))
 if target<=vals:
  for r,c in comp: out[r][c]=7
print('\n'.join(' '.join(map(str,row)) for row in out))
